//! Byte-for-byte conformance against `reference/vectors/10-cpu/cpu.json`,
//! generated by `reference/gen_vectors_09_10.py`. The replay mirrors
//! that generator: rebuild the recorded program, expand it, run the
//! virtual machine padded, generate the witness, and compare every
//! recorded quantity (decode table, ROM head, `upc_of_pc`, trace
//! prefix, per-row witness popcounts, public inputs, stats, layout).

use std::collections::BTreeMap;
use std::path::PathBuf;

use om_circuit::circuit::{Params, check, layout, public_inputs, stats, witness};
use om_isa::bytecode::{COLUMNS, VirtualMachine, expand};
use om_isa::riscv::decode;
use serde_json::Value;

const A: u32 = 8;

fn load() -> Value {
    let path =
        PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../reference/vectors/10-cpu/cpu.json");
    let text = std::fs::read_to_string(&path).unwrap_or_else(|e| panic!("read {path:?}: {e}"));
    serde_json::from_str(&text).unwrap()
}

/// Parse the generator's int encoding: a JSON number, or a `"0x…"`
/// string for values `> 9` in `rom_head`, plain hex elsewhere.
fn hex_or_num(v: &Value) -> u64 {
    match v {
        Value::Number(_) => v.as_u64().unwrap(),
        Value::String(s) => u64::from_str_radix(s.strip_prefix("0x").unwrap_or(s), 16).unwrap(),
        _ => panic!("bad numeric value {v}"),
    }
}

fn hex64(v: &Value) -> u64 {
    let s = v.as_str().unwrap();
    u64::from_str_radix(s.strip_prefix("0x").unwrap_or(s), 16).unwrap()
}

#[test]
fn cpu_vector_replay() {
    let d = load();

    // Decoder table.
    for e in d["decode"].as_array().unwrap() {
        let word = u32::from_str_radix(e["word"].as_str().unwrap(), 16).unwrap();
        let i = decode(word);
        assert_eq!(i.op.name(), e["name"].as_str().unwrap(), "word {word:08x}");
        assert_eq!(u64::from(i.rd), e["rd"].as_u64().unwrap());
        assert_eq!(u64::from(i.rs1), e["rs1"].as_u64().unwrap());
        assert_eq!(u64::from(i.rs2), e["rs2"].as_u64().unwrap());
        assert_eq!(i.imm, e["imm"].as_i64().unwrap());
    }

    // Program image, expansion, padded execution.
    let code: BTreeMap<u64, u32> = d["program"]["code"]
        .as_object()
        .unwrap()
        .iter()
        .map(|(k, v)| {
            (
                u64::from_str_radix(k, 16).unwrap(),
                u32::from_str_radix(v.as_str().unwrap(), 16).unwrap(),
            )
        })
        .collect();
    let entry = u64::from_str_radix(d["program"]["entry_pc"].as_str().unwrap(), 16).unwrap();
    let p = expand(&code, entry);

    // rom_head: the nonzero columns of the first 8 ROM rows.
    let rom_head = d["rom_head"].as_array().unwrap();
    assert_eq!(rom_head.len(), 8);
    for (row, expect) in p.rom.iter().zip(rom_head) {
        let expect = expect.as_object().unwrap();
        for col in &COLUMNS {
            let got = row.get(col.name).unwrap();
            match expect.get(col.name) {
                Some(v) => assert_eq!(got, hex_or_num(v), "rom col {}", col.name),
                None => assert_eq!(got, 0, "rom col {} should be absent (zero)", col.name),
            }
        }
    }
    // upc_of_pc.
    let want_upc: BTreeMap<u64, u32> = d["upc_of_pc"]
        .as_object()
        .unwrap()
        .iter()
        .map(|(k, v)| {
            (
                u64::from_str_radix(k, 16).unwrap(),
                v.as_u64().unwrap() as u32,
            )
        })
        .collect();
    assert_eq!(p.upc_of_pc, want_upc);

    let vm = VirtualMachine::new(p.clone(), &BTreeMap::new(), A)
        .run_padded(1000)
        .expect("vm");
    assert_eq!(vm.trace.len() as u64, d["cycles"].as_u64().unwrap());
    assert_eq!(vm.exit_code, d["exit_code"].as_u64().unwrap());

    // Trace prefix.
    for (rec, e) in vm.trace.iter().zip(d["trace_prefix"].as_array().unwrap()) {
        assert_eq!(u64::from(rec.upc), e["upc"].as_u64().unwrap());
        assert_eq!(u64::from(rec.rd), e["rd"].as_u64().unwrap());
        assert_eq!(rec.v1, hex64(&e["v1"]));
        assert_eq!(rec.v2, hex64(&e["v2"]));
        assert_eq!(rec.rd_val, hex64(&e["rd_val"]));
        assert_eq!(u64::from(rec.next_upc), e["next_upc"].as_u64().unwrap());
    }

    // Witness: accepted, and with the recorded per-row popcounts.
    let par = Params {
        ram_log_words: A,
        log_cycles: 2,
    };
    let w = witness(&vm.trace, &par, None);
    let pub_ = public_inputs(&p, vm.exit_code);
    assert!(check(&w, &pub_, &par, Some(&p)));
    let ones: Vec<u64> = d["witness_row_ones"]
        .as_array()
        .unwrap()
        .iter()
        .map(|v| v.as_u64().unwrap())
        .collect();
    assert_eq!(w.len(), ones.len());
    for (row, &want) in w.iter().zip(&ones) {
        assert_eq!(row.iter().filter(|&&b| b).count() as u64, want);
    }
    assert_eq!(
        u64::from(pub_.entry_upc),
        d["public"]["entry_upc"].as_u64().unwrap()
    );
    assert_eq!(pub_.exit_code, d["public"]["exit_code"].as_u64().unwrap());

    // Stats.
    let s = stats(&par);
    let st = &d["stats"];
    let eq =
        |got: usize, key: &str| assert_eq!(got as u64, st[key].as_u64().unwrap(), "stats.{key}");
    eq(s.cycles_per_instance, "cycles_per_instance");
    eq(s.nw, "NW");
    eq(s.used_bits, "used_bits");
    eq(s.direct_bits_per_cycle, "direct_bits_per_cycle");
    eq(
        s.direct_bits_per_instance_state,
        "direct_bits_per_instance_state",
    );
    eq(s.virtual_bits_per_cycle, "virtual_bits_per_cycle");
    eq(s.s1_rows, "s1_rows");
    eq(s.s2_rows, "s2_rows");
    eq(s.s1_rows_per_cycle, "s1_rows_per_cycle");
    eq(s.s2_rows_per_cycle, "s2_rows_per_cycle");
    eq(s.s1_nnz, "s1_nnz");
    eq(s.s2_nnz, "s2_nnz");

    // Layout: all 37 segments, ids in this order.
    let segs = layout(&par);
    let want = d["layout"].as_array().unwrap();
    assert_eq!(segs.len(), want.len());
    for (seg, e) in segs.iter().zip(want) {
        assert_eq!(seg.name, e["name"].as_str().unwrap());
        assert_eq!(
            seg.log_size as u64,
            e["log_size"].as_u64().unwrap(),
            "{}",
            seg.name
        );
        assert_eq!(
            seg.offset as u64,
            e["offset"].as_u64().unwrap(),
            "{}",
            seg.name
        );
        assert_eq!(
            seg.kind.as_str(),
            e["kind"].as_str().unwrap(),
            "{}",
            seg.name
        );
        assert_eq!(
            seg.owner.as_str(),
            e["owner"].as_str().unwrap(),
            "{}",
            seg.name
        );
    }
}
